def augment(x):
    """Randomly mirror and turn a batch. A galaxy has no 'up'."""
    if torch.rand(1) < 0.5:
        x = x.flip(3)                                   # mirror left-right
    turns = int(torch.randint(0, 4, (1,)))              # 0, 90, 180, 270
    return torch.rot90(x, turns, dims=(2, 3))

